import * as T from './three.module.js';
import {worldMaterial} from './valorant-render.js?v=20261005-lighting2';
import {decodeMapLighting,materialHighlight} from './map-lighting.js?v=20261005-lighting2';
import {fetchWeaponAsset,weaponAssetURL} from './weapon-assets.js?v=20261005-lighting2';
import {decodeGoldSrcAsset,loadGoldSrc} from './goldsrc-model.js?v=20261005-lighting2';
import {bleedMaskedTexture} from './map-textures.js?v=20261005-lighting2';
import {MapNavigation} from './map-navigation.js?v=20261005-lighting2';
// Cyan tool surfaces in these BSP imports are seals, not visible architecture.
export const isMapSeal=t=>t?.name?.toLowerCase()==='aa_turkuaz';
export const MAPS=[{key:'ascent',name:'亚海悬城',en:'ASCENT',color:'#c7b9a0'},{key:'pearl',name:'深海遗珠',en:'PEARL',color:'#91b8ce'},{key:'lotus',name:'莲华古城',en:'LOTUS',color:'#b4bf96'},{key:'sunset',name:'日落之城',en:'SUNSET',color:'#deb2a5'},{key:'fracture',name:'裂变峡谷',en:'FRACTURE',color:'#b8c5a1'},{key:'breeze',name:'微风岛屿',en:'BREEZE',color:'#90cad1'},{key:'training',name:'空岛街区',en:'TRAINING',color:'#c0baa7'}];
export async function loadNativeMap(key,{onProgress=()=>{},renderer}={}){
 const base='./assets/maps/'+key+'/',buffer=await fetchWeaponAsset(base+'map.json.gz?v=20261005-lighting2',{onProgress,timeout:60000}),plain=await decodeGoldSrcAsset(buffer),data=JSON.parse(new TextDecoder().decode(plain)),group=new T.Group(),meshes=[],textures=[],materials=[],geometries=[];group.name='native-map-'+key;
 try {
 const lightPromise=fetchWeaponAsset(base+'lighting.bin.gz?v=20261005-lighting2',{timeout:10000,attempts:1}).then(decodeGoldSrcAsset).then(bytes=>decodeMapLighting(bytes,data.meshes)).catch(e=>{console.warn('地图附加光照未载入，使用原始烘焙光照',key,e.message);return null;});
 const maps=await Promise.all(data.textures.map(async t=>{if(!t.file)return null;const tex=await new T.TextureLoader().loadAsync(weaponAssetURL(base+t.file));tex.colorSpace=T.SRGBColorSpace;tex.flipY=false;tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.anisotropy=Math.min(8,renderer?.capabilities?.getMaxAnisotropy?.()||1);textures.push(tex);return tex;}));
 const lighting=await lightPromise;
 for(const [index,m]of data.meshes.entries()){if(isMapSeal(data.textures[m.texture]))continue;const g=new T.BufferGeometry();for(const[name,values,n]of [['position',m.positions,3],['normal',m.normals,3],['uv',m.uv,2],['color',m.colors,3]])g.setAttribute(name,new T.Float32BufferAttribute(values,n));if(lighting)g.setAttribute('staticLight',new T.Uint8BufferAttribute(lighting[index],3,true));g.computeBoundingSphere();const t=data.textures[m.texture],material=worldMaterial({staticLighting:!!lighting,highlight:materialHighlight(t.name),map:maps[m.texture],vertexColors:true,color:maps[m.texture]?0xffffff:0xb8b5ae,alphaTest:t.alpha?.5:0});const mesh=new T.Mesh(g,material);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);meshes.push(mesh);materials.push(material);geometries.push(g);}
 // Repeated static props share one mesh and texture bank through instancing.
 const props=new Map();for(const p of data.props){if(!props.has(p.file))props.set(p.file,[]);props.get(p.file).push(p);}
 for(const[file,list]of props){try{const source=await loadGoldSrc(base+file),parsed=Object.create(source);parsed.textures=source.textures.map(bleedMaskedTexture);const rig=parsed.instantiate({world:true});rig.sample(0,0);rig.model.updateMatrixWorld(true);for(const m of rig.meshes){const g=m.geometry.clone(),position=g.attributes.position,v=new T.Vector3();for(let i=0;i<position.count;i++){m.getVertexPosition(i,v).applyMatrix4(m.matrixWorld);position.setXYZ(i,v.x,v.y,v.z);}g.deleteAttribute('skinIndex');g.deleteAttribute('skinWeight');g.computeVertexNormals();const im=new T.InstancedMesh(g,m.material,list.length);im.frustumCulled=false;im.castShadow=!m.userData.nativeEffect;im.receiveShadow=true;list.forEach((p,i)=>{const transform=new T.Matrix4().compose(new T.Vector3(...p.position),new T.Quaternion().setFromEuler(new T.Euler(0,p.angles[1]*Math.PI/180,0)),new T.Vector3(1,1,1));im.setMatrixAt(i,transform);});group.add(im);geometries.push(g);}geometries.push(...rig.meshes.map(m=>m.geometry));materials.push(...rig.meshes.map(m=>m.material));textures.push(...rig.meshes.map(m=>m.material.map).filter(Boolean));rig.skeleton.dispose();}catch(e){console.warn('Map prop skipped',file,e.message);}}
 let sky=null;if(data.sky.length===6){const faces=['rt','lf','up','dn','bk','ft'].map(s=>data.sky.find(f=>f.endsWith(s+'.webp')));if(faces.every(Boolean)){sky=await new T.CubeTextureLoader().loadAsync(faces.map(f=>weaponAssetURL(base+f)));sky.colorSpace=T.SRGBColorSpace;textures.push(sky);}}
 const navigation=new MapNavigation(data);data.sites=data.sites.map(s=>navigation.safePoint(s));for(const side of ['attack','defend'])data.spawns[side]=data.spawns[side].map(s=>navigation.safePoint(s));return {key,data,group,meshes,navigation,sky,dispose(){group.removeFromParent();new Set(geometries).forEach(g=>g.dispose());new Set(materials).forEach(m=>m.dispose());new Set(textures).forEach(t=>t.dispose());}};
 }catch(e){new Set(geometries).forEach(g=>g.dispose());new Set(materials).forEach(m=>m.dispose());new Set(textures).forEach(t=>t.dispose());throw e;}
}
